#include <windows.h>
#include <dshow.h>
#include <mmreg.h>
#include <cstdio>
#include <vector>
#include <string>
static void freeType(AM_MEDIA_TYPE& mt){if(mt.cbFormat)CoTaskMemFree(mt.pbFormat);if(mt.pUnk)mt.pUnk->Release();mt={};}
static IPin* pin(IBaseFilter* f,PIN_DIRECTION direction){IEnumPins* e=nullptr;if(FAILED(f->EnumPins(&e)))return nullptr;IPin* p=nullptr;while(e->Next(1,&p,nullptr)==S_OK){PIN_DIRECTION d;p->QueryDirection(&d);if(d==direction){e->Release();return p;}p->Release();}e->Release();return nullptr;}
static HRESULT sony(const wchar_t* module,const wchar_t* guid,IBaseFilter** filter){CLSID clsid;CLSIDFromString(guid,&clsid);auto hr=CoCreateInstance(clsid,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(filter));if(SUCCEEDED(hr))return hr;
    std::wstring path=L"C:\\Program Files (x86)\\Sony\\Music Center\\Sony.Earth\\";SetDllDirectoryW(path.c_str());path+=module;HMODULE dll=LoadLibraryW(path.c_str());if(!dll)return HRESULT_FROM_WIN32(GetLastError());auto factory=reinterpret_cast<HRESULT(STDAPICALLTYPE*)(REFCLSID,REFIID,void**)>(GetProcAddress(dll,"DllGetClassObject"));if(!factory)return E_NOINTERFACE;IClassFactory* cf=nullptr;hr=factory(clsid,IID_PPV_ARGS(&cf));if(SUCCEEDED(hr)){hr=cf->CreateInstance(nullptr,IID_PPV_ARGS(filter));cf->Release();}return hr;}
static void format(const wchar_t* label,IPin* p){AM_MEDIA_TYPE mt{};auto hr=p->ConnectionMediaType(&mt);if(SUCCEEDED(hr)&&mt.formattype==FORMAT_WaveFormatEx&&mt.cbFormat>=16){WAVEFORMATEX f{};memcpy(&f,mt.pbFormat,(mt.cbFormat<sizeof(f)?mt.cbFormat:sizeof(f)));wprintf(L"FORMAT %s rate=%lu bits=%u ch=%u tag=%u\n",label,f.nSamplesPerSec,f.wBitsPerSample,f.nChannels,f.wFormatTag);}else wprintf(L"FORMAT %s hr=%08lx\n",label,ULONG(hr));freeType(mt);}
int wmain(int argc,wchar_t** argv){if(argc<3){fwprintf(stderr,L"Usage: bypass_test file.flac direct|chain|baseline [seconds] [monitor.dll]\n");return 2;}if(argc>4){if(!LoadLibraryW(argv[4])){wprintf(L"monitor load error=%lu\n",GetLastError());return 3;}Sleep(1500);}CoInitializeEx(nullptr,COINIT_APARTMENTTHREADED);IGraphBuilder* graph=nullptr;HRESULT hr=CoCreateInstance(CLSID_FilterGraph,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&graph));if(FAILED(hr))return 4;
    std::vector<IBaseFilter*> filters;IBaseFilter* source=nullptr;hr=sony(L"OmgFlacSrc.ax",L"{028A95AA-C956-4874-AD10-C657DB1B00F4}",&source);wprintf(L"CREATE source hr=%08lx\n",ULONG(hr));if(SUCCEEDED(hr)){filters.push_back(source);hr=graph->AddFilter(source,L"Sony FLAC");IFileSourceFilter* fs=nullptr;if(SUCCEEDED(hr))hr=source->QueryInterface(IID_PPV_ARGS(&fs));if(fs){hr=fs->Load(argv[1],nullptr);fs->Release();}wprintf(L"LOAD hr=%08lx\n",ULONG(hr));}
    bool chain=wcscmp(argv[2],L"direct")!=0;bool baseline=wcscmp(argv[2],L"baseline")==0;
    struct Spec {const wchar_t* module;const wchar_t* guid;const wchar_t* name;};
    Spec specs[]={{L"OmgDseeHxFilter.ax",L"{A481D160-AB4D-4B97-93FE-C1F4B4B781DF}",L"DSEE"},{L"SeamlessFilter.ax",L"{6AF73F1F-1266-46E6-9A36-EE75E4BA10BB}",L"Seamless"},{L"OmgEqxlFilter.ax",L"{5C968488-5E35-4CFE-98A1-A51C838797DB}",L"EQ"}};
    if(chain&&SUCCEEDED(hr))for(int i=baseline?0:1;i<3;++i){IBaseFilter* f=nullptr;hr=sony(specs[i].module,specs[i].guid,&f);wprintf(L"CREATE %s hr=%08lx\n",specs[i].name,ULONG(hr));if(FAILED(hr))break;filters.push_back(f);hr=graph->AddFilter(f,specs[i].name);if(FAILED(hr))break;}
    if(SUCCEEDED(hr)){IBaseFilter* renderer=nullptr;hr=CoCreateInstance(CLSID_DSoundRender,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&renderer));wprintf(L"CREATE renderer hr=%08lx\n",ULONG(hr));if(renderer){filters.push_back(renderer);hr=graph->AddFilter(renderer,L"DirectSound");}}
    for(size_t i=1;SUCCEEDED(hr)&&i<filters.size();++i){IPin* out=pin(filters[i-1],PINDIR_OUTPUT);IPin* in=pin(filters[i],PINDIR_INPUT);if(!out||!in){hr=E_NOINTERFACE;}else{hr=graph->ConnectDirect(out,in,nullptr);wprintf(L"CONNECT edge=%zu hr=%08lx\n",i,ULONG(hr));if(SUCCEEDED(hr)){format(L"output",out);format(L"input",in);}}if(out)out->Release();if(in)in->Release();}
    if(SUCCEEDED(hr)&&argc>3&&_wtoi(argv[3])>0){IMediaControl* control=nullptr;IMediaSeeking* seek=nullptr;graph->QueryInterface(IID_PPV_ARGS(&control));graph->QueryInterface(IID_PPV_ARGS(&seek));if(seek){LONGLONG start=300000000;auto result=seek->SetPositions(&start,AM_SEEKING_AbsolutePositioning,nullptr,AM_SEEKING_NoPositioning);wprintf(L"SEEK 30s hr=%08lx\n",ULONG(result));seek->Release();}if(control){hr=control->Run();wprintf(L"RUN hr=%08lx\n",ULONG(hr));if(SUCCEEDED(hr)){Sleep(_wtoi(argv[3])*1000);IMediaEvent* events=nullptr;graph->QueryInterface(IID_PPV_ARGS(&events));if(events){long code;LONG_PTR a,b;while(events->GetEvent(&code,&a,&b,0)==S_OK){wprintf(L"EVENT code=%ld a=%08lx\n",code,ULONG(a));events->FreeEventParams(code,a,b);}events->Release();}}control->Stop();control->Release();}}
    for(auto f:filters)f->Release();graph->Release();CoUninitialize();wprintf(L"END pid=%lu hr=%08lx\n",GetCurrentProcessId(),ULONG(hr));return FAILED(hr)?1:0;}
